// MsgServer is the server API for Msg service.
type MsgServer interface {
	// UpdateParams defines a (governance) operation for updating the module
	// parameters. The authority defaults to the x/gov module account.
	UpdateParams(context.Context, *MsgUpdateParams) (*MsgUpdateParamsResponse, error)
	// Post creates a post.
	Post(context.Context, *MsgPost) (*MsgPostResponse, error)
	// Edit updates an existing post or comment (override refers to txhash being edited).
	Edit(context.Context, *MsgEdit) (*MsgEditResponse, error)
	// Vote creates a vote.
	Vote(context.Context, *MsgVote) (*MsgVoteResponse, error)
	// SetUsername persists a username for the signer.
	SetUsername(context.Context, *MsgSetUsername) (*MsgSetUsernameResponse, error)
	// FollowModerator adds a moderator to the signer's followed list (capped deque).
	FollowModerator(context.Context, *MsgFollowModerator) (*MsgFollowModeratorResponse, error)
	// UnfollowModerator removes a moderator from the signer's followed list.
	UnfollowModerator(context.Context, *MsgUnfollowModerator) (*MsgUnfollowModeratorResponse, error)
	// FollowUser adds a user to the signer's followed users list (capped deque).
	FollowUser(context.Context, *MsgFollowUser) (*MsgFollowUserResponse, error)
	// UnfollowUser removes a user from the signer's followed users list.
	UnfollowUser(context.Context, *MsgUnfollowUser) (*MsgUnfollowUserResponse, error)
	// FollowTopic adds a topic to the signer's followed topics list (capped deque).
	FollowTopic(context.Context, *MsgFollowTopic) (*MsgFollowTopicResponse, error)
	// UnfollowTopic removes a topic from the signer's followed topics list.
	UnfollowTopic(context.Context, *MsgUnfollowTopic) (*MsgUnfollowTopicResponse, error)
	// BlockPost blocks a post txhash (persisted on-chain).
	BlockPost(context.Context, *MsgBlockPost) (*MsgBlockPostResponse, error)
	// UnblockPost unblocks a post txhash (persisted on-chain).
	UnblockPost(context.Context, *MsgUnblockPost) (*MsgUnblockPostResponse, error)
	// BlockUser blocks a user address (persisted on-chain).
	BlockUser(context.Context, *MsgBlockUser) (*MsgBlockUserResponse, error)
	// UnblockUser unblocks a user address (persisted on-chain).
	UnblockUser(context.Context, *MsgUnblockUser) (*MsgUnblockUserResponse, error)
	// Delete marks a post or comment as deleted (only emits event for indexer).
	Delete(context.Context, *MsgDelete) (*MsgDeleteResponse, error)
	// SendTokens sends tokens from signer to target.
	SendTokens(context.Context, *MsgSendTokens) (*MsgSendTokensResponse, error)
	// SetLevel sets the user level for an address (governance only).
	SetLevel(context.Context, *MsgSetLevel) (*MsgSetLevelResponse, error)
	// PunishValidator slashes/jails/tombstones a validator (governance only).
	PunishValidator(context.Context, *MsgPunishValidator) (*MsgPunishValidatorResponse, error)
	// MintTokens mints new tokens to a target address (governance only).
	MintTokens(context.Context, *MsgMintTokens) (*MsgMintTokensResponse, error)
	// BurnTokens burns tokens from a target address (governance only).
	BurnTokens(context.Context, *MsgBurnTokens) (*MsgBurnTokensResponse, error)
	// UpgradeLevel upgrades user tier (requires token payment, no PoW).
	UpgradeLevel(context.Context, *MsgUpgradeLevel) (*MsgUpgradeLevelResponse, error)
	// SetAutoRenewal sets the auto_renew flag for a user's subscription.
	// Paid subscribers must pay via reserve; PoW is not allowed.
	SetAutoRenewal(context.Context, *MsgSetAutoRenewal) (*MsgSetAutoRenewalResponse, error)
	// BridgeBurn burns MIRAGE tokens for bridging to an external chain (e.g., Solana).
	// Uses envelope fields for relay signature verification.
	BridgeBurn(context.Context, *MsgBridgeBurn) (*MsgBridgeBurnResponse, error)
	// BridgeAttestBurned allows validators to attest to a burn on an external chain (inbound).
	// When 2/3 threshold is met, tokens are minted on Mirage.
	// Does NOT use envelope - signed directly by validator's consensus key.
	BridgeAttestBurned(context.Context, *MsgBridgeAttestBurned) (*MsgBridgeAttestBurnedResponse, error)
	// BridgeAttestMinted allows validators to attest to a mint on an external chain (outbound).
	// When 2/3 threshold is met, BridgeConfirmed event is emitted.
	// Signed by validator's operator key.
	BridgeAttestMinted(context.Context, *MsgBridgeAttestMinted) (*MsgBridgeAttestMintedResponse, error)
}

